INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 32, 'theory', 'Quiz: Security and the final exam');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 32, 0, 'A service is refused access to an image copied from another server, chmod and chown change nothing, and audit.log has avc: denied with tcontext ...:default_t:s0. What do you do first?', '["Run setenforce 0 and leave it", "Make a policy module with audit2allow", "Record a semanage fcontext rule and run restorecon", "Set permissions 777 on the directory"]', 2, 'The type default_t says the file never got its own label. That is a wrong label, and it is fixed with a rule and restorecon. A policy module or permissive mode only hides the problem.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 32, 1, 'SELinux is in permissive mode. What happens when a process violates the policy?', '["The action is allowed and an AVC record with permissive=1 is logged", "The action is denied and nothing is logged", "The action is denied and a record is logged", "The process is stopped by a signal"]', 0, 'Permissive mode only logs: the action goes through, and permissive=1 shows that no real refusal happened. This is how a policy is tested before turning it on.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 32, 2, 'The kernel log has many lines apparmor="ALLOWED" operation="open" with the profile libvirt-<uuid>. What does it mean?', '["The profile is not loaded", "The profile rejected these accesses", "A profile rule with the audit flag allowed them", "The profile is in complain mode: violations are allowed but logged"]', 3, 'In complain mode what enforce would reject is logged as ALLOWED. The audit flag logs allowed accesses with the status AUDIT instead. After debugging the profile is put back to enforce with aa-enforce.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 32, 3, 'Which command watches /etc/passwd for changes and tags the events with a key for ausearch?', '["auditctl -w /etc/passwd -p r", "auditctl -w /etc/passwd -p wa -k passwd_changes", "auditctl -k /etc/passwd -w wa", "ausearch -w /etc/passwd"]', 1, 'Option -w names the path, -p wa selects writes and attribute changes, and -k adds a tag for ausearch -k. ausearch does not create rules.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 32, 4, 'Two virtual machines run in the domain svirt_t. What stops one from reading the image of the other?', '["They have different user numbers", "Permissions 600 and the owner of the image", "Different category pairs on the process and the image", "The images lie on different block devices"]', 2, 'In sVirt all guests share one domain, and a category pair such as c123,c456 tells them apart: a process may open only a file with the same pair. Owner and permissions do not replace that.');
